SELECT *
FROM (SELECT t.*, ROWNUM rn
      FROM BOOKMAN."user" t
      WHERE ROWNUM <= #{end}
      ORDER BY "uid") rt
WHERE rn >= #{start}

SELECT *
FROM (SELECT t.*, ROWNUM rn
      FROM BOOKMAN."deleted_user" t
      WHERE ROWNUM <= #{end}
      ORDER BY "uid") rt
WHERE rn >= #{start}
